   Copy and markup are spec-exact. Only layout styles live in hero.css. */

import type { ComponentType, ReactNode } from "react";
import { ArrowRight } from "./icons";

export interface HeroCopyProps {
  headlineText: string;
  signupHref: string;
  signinHref: string;
  onSignUp?: () => void;
  onSignIn?: () => void;
  buttonsRef?: React.RefObject<HTMLDivElement | null>;
  chipsRef?: React.RefObject<HTMLDivElement | null>;
  microRef?: React.RefObject<HTMLParagraphElement | null>;
  largeTouch?: boolean;
}

export function HeroCopy({
  headlineText,
  signupHref,
  signinHref,
  buttonsRef,
  chipsRef,
  microRef,
  largeTouch,
}: HeroCopyProps) {
  const words = headlineText.split(/\s+/);
  const visibleText = words.join(" ");

  return (
    <div className="hero-copy">
      <p className="hero-eyebrow" id="hero-eyebrow">
        AI-AUDITED ESCROW FOR DIGITAL WORK
      </p>

      <h1 className="hero-h1" aria-labelledby="hero-headline-text">
        <span className="vh">{visibleText}</span>
        {words.map((word, i) => (
          <span key={i} className="word" aria-hidden="true">
            {word}
          </span>
        ))}
      </h1>

      <p className="hero-body">
        VaultPay AI holds the deliverables and your payment side by side.
        Ask the AI anything about the work. It runs real checks, not guesses.
        Approve, and PayPal releases the funds and unlocks the files.
      </p>

      <div className="hero-cta-row" ref={buttonsRef} data-largetouch={largeTouch ? "1" : undefined}>
        <a
          className="hero-btn primary arrow"
          href={signupHref}
          onClick={(e) => {
            e.preventDefault();
          }}
          aria-label="Sign up"
        >
          Sign up
          <ArrowRight />
        </a>
        <a
          className="hero-btn mark"
          href={signinHref}
          onClick={(e) => {
            e.preventDefault();
          }}
          aria-label="Sign in"
        >
          <LockOpenMark style={{ position: "static", margin: 0, width: 18, height: 18, color: "currentColor" }} />
          Sign in
        </a>
      </div>

      <p className="hero-micro" ref={microRef}>
        SANDBOX DEMO · NO REAL MONEY
      </p>

      <div className="hero-chips" ref={chipsRef} aria-label="Vault features">
        <span className="hero-chip">FUNDS HELD, NOT SPENT</span>
        <span className="hero-chip">REAL CHECKS, NOT CLAIMS</span>
        <span className="hero-chip">FILES UNLOCK ON CAPTURE</span>
      </div>
    </div>
  );
}

const LockOpenMark: ComponentType<{ style?: React.CSSProperties }> = (props) => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.75"
