{"kind":"tool","id":"aohssE46kcM","toolName":"write_file","input":{"path":"src/components/HeroVault.tsx","instructions":"HeroVault.tsx — canvas frame 1, hotspot overlay, wheel layer, rim light, responsive","content":"/* HeroVault.tsx — VaultPay AI hero vault: canvas frame 1 + hotspot overlay.
   Single frame drawn at contain fit; hotspot overlay is percent of drawn rect. */

import { useRef, useEffect, useCallback, useState } from "react";

export interface HeroVaultProps {
  frameSrc?: string;
  wheelRef?: React.RefObject<HTMLDivElement | null>;
  rimRef?: React.RefObject<HTMLDivElement | null>;
  keypadRef?: React.RefObject<HTMLDivElement | null>;
  seamRef?: React.RefObject<HTMLDivElement | null>;
  isLargeTouch?: boolean;
}

export function HeroVault({
  frameSrc = "/vault-frames/f_001.webp",
  wheelRef,
  rimRef,
  keypadRef,
  seamRef,
  isLargeTouch,
}: HeroVaultProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const imageRef = useRef<HTMLImageElement | null>(null);
  const [ready, setReady] = useState(false);
  const [rect, setRect] = useState({ dw: 0, dh: 0, dx: 0, dy: 0, w: 0, h: 0 });

  const fit = useCallback((imgW: number, imgH: number, w: number, h: number) => {
    const s = Math.max(w / imgW, h / imgH);
    const dw = imgW * s;
    const dh = imgH * s;
    return { dx: (w - dw) / 2, dy: (h - dh) / 2, dw, dh };
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const img = new Image();
    img.src = frameSrc;
    img.decoding = "async";
    img.onload = () => {
      imageRef.current = img;
      const dpr = Math.min(2, window.devicePixelRatio || 1);
      const w = canvas.clientWidth;
      const h = canvas.clientHeight;
      const { width, height, clientWidth, clientHeight } = canvas;
      const ctx = canvas.getContext("2d");
      if (!ctx) return;
      const { dx, dy, dw, dh } = fit(img.width, img.height, w, h);
