{"kind":"tool","id":"aoi8ZdtyDJs","toolName":"write_file","input":{"path":"src/components/hero-timeline.ts","instructions":"Hero timeline: entrance GSAP + idle loops + parallax + scroll handoff, spec timings","content":"/* hero-timeline.ts — VaultPay AI hero entrance, idle loops, parallax, scroll handoff.
   Spec timings and behaviors only. Call play() once on mount. */

import gsap from "gsap";
import type { RefObject } from "react";

export interface HeroTimelineAPI {
  play: () => void;
  pause: () => void;
  setProgress: (p: number) => void;
}

export function createHeroTimeline({
  pageRef,
  frameRef,
  rimRef,
  eyebrowRef,
  headlineRef,
  bodyRef,
  buttonsRef,
  chipsRef,
  microRef,
  vaultRef,
  wheelRef,
  keypadRef,
  seamRef,
  hingeRef,
  heroCopyRef,
  heroVaultRef,
  reducedMotion,
  isLargeTouch,
}: {
  pageRef: RefObject<HTMLElement | null>;
  frameRef: RefObject<HTMLImageElement | null>;
  rimRef: RefObject<HTMLElement | null>;
  eyebrowRef: RefObject<HTMLElement | null>;
  headlineRef: RefObject<HTMLElement | null>;
  bodyRef: RefObject<HTMLElement | null>;
  buttonsRef: RefObject<HTMLElement | null>;
  chipsRef: RefObject<HTMLElement | null>;
  microRef: RefObject<HTMLElement | null>;
  vaultRef: RefObject<HTMLElement | null>;
  wheelRef: RefObject<HTMLElement | null>;
  keypadRef: RefObject<HTMLElement | null>;
  seamRef: RefObject<HTMLElement | null>;
  hingeRef: RefObject<HTMLElement | null>;
  heroCopyRef: RefObject<HTMLElement | null>;
  heroVaultRef: RefObject<HTMLElement | null>;
  reducedMotion: RefObject<boolean>;
  isLargeTouch: RefObject<boolean>;
}): HeroTimelineAPI {
  let ctx: gsap.Context | null = null;
  let idleRAF: number | null = null;

  function build() {
    ctx = gsap.context(() => {
      const vault = vaultRef.current;
      const frame = frameRef.current;
      const rim = rimRef.current;
      const eyebrow = eyebrowRef.current;
      const headline = headlineRef.current;
      const body = bodyRef.current;
      const buttons = buttonsRef.current;
      const chips = chipsRef.current;
      const micro = microRef.current;
      const heroCopy = heroCopyRef.current;
      const heroVault = heroVaultRef.current;
      const wheel = wheelRef.current;
      const keypad = keypadRef.current;
      const seam = seamRef.current;
      const hinge = hingeRef.current;
      if (!vault || !heroCopy || !heroVault) return;

      const isReduced = reducedMotion.current;
      const touch = isLargeTouch.current;

      // page bg fades in first
      gsap.fromTo(pageRef.current, { opacity: 0 }, {
        opacity: 1,
        duration: isReduced ? 0.001 : 0.618,
        ease: "power3.out",
        overwrite: "auto",
      });

      // vault entrance: y +34, opacity 0, scale 0.97 -> 0,1,1
      gsap.fromTo(vault, {
        y: 34,
        opacity: 0,
        scale: 0.97,
      }, {
        y: 0,
        opacity: 1,
        scale: 1,
        duration: isReduced ? 0.001 : 1.618,
        ease: isReduced ? "power1.out" : "expo.out",
        overwrite: "auto",
      });

      // teal rim fade in 0.618
      gsap.fromTo(rim, { opacity: 0 }, {
        opacity: 1,
        duration: isReduced ? 0.001 : 0.618,
        ease: "power2.out",
        overwrite: "auto",
      });

      // eyebrow 0.382
      gsap.fromTo(eyebrow, {
        y: 13,
        opacity: 0,
      }, {
        y: 0,
        opacity: 1,
        duration: isReduced ? 0.001 : 0.382,
        ease: "power2.out",
        delay: isReduced ? 0 : 0.382,
        overwrite: "auto",
      });

      // headline word-by-word
      if (headline) {
        const words = headline.querySelectorAll<HTMLElement>(".word");
        gsap.fromTo(words, {
          y: 34,
          opacity: 0,
        }, {
          y: 0,
          opacity: 1,
          duration: isReduced ? 0.001 : 0.618,
          ease: "power2.out",
          stagger: isReduced ? 0 : 0.0618,
          delay: isReduced ? 0 : 0.618,
          overwrite: "auto",
        });
      }

      // body 1.000
      gsap.fromTo(body, {
        y: 21,
        opacity: 0,
      }, {
        y: 0,
        opacity: 1,
        duration: isReduced ? 0.001 : 0.618,
        ease: "power2.out",
        delay: isReduced ? 0 : 1.000,
        overwrite: "auto",
      });

      // buttons 1.382, stagger 0.236
      if (buttons) {
        const items = buttons.querySelectorAll<HTMLElement>(".hero-btn");
        gsap.fromTo(items, {
          y: 21,
          opacity: 0,
        }, {
          y: 0,
          opacity: 1,
          duration: isReduced ? 0.001 : 0.618,
          ease: "power2.out",
          stagger: isReduced ? 0 : 0.236,
          delay: isReduced ? 0 : 1.382,
          overwrite: "auto",
        });
      }

      // micro + chips 1.618, stagger 0.1
      const tail = [micro, chips].filter(Boolean) as HTMLElement[];
      if (tail.length) {
        gsap.fromTo(tail, {
          opacity: 0,
        }, {
          opacity: 1,
          duration: isReduced ? 0.001 : 0.618,
          ease: "power2.out",
          stagger: isReduced ? 0 : 0.1,
          delay: isReduced ? 0 : 1.618,
          overwrite: "auto",
        });
      }

      // idle loops only when visible and not reduced
      if (!isReduced) {
        const float = { y: 0 };
        gsap.to(float, {
          y: 8,
          duration: 3.09,
          ease: "sine.inOut",
          repeat: -1,
          yoyo: true,
          overwrite: "auto",
        });
        gsap.to(vault, {
          y: float.y,
          duration: 0.001,
          overwrite: "auto",
        });

        if (wheel) {
          gsap.to(wheel, {
            opacity: 0.6,
            duration: 1.309,
            ease: "sine.inOut",
            repeat: -1,
            yoyo: true,
            overwrite: "auto",
          });
        }

        if (isLargeTouch.current && typeof window !== "undefined") {
          const handleParallax = () => {
            if (idleRAF) return;
            const onMove = () => {
              const x = window.innerWidth / 2;
              const y = window.innerHeight / 2;
              // handled during hover; placeholder for pointer state
            };
            window.addEventListener("pointermove", onMove, { passive: true });
            return () => window.removeEventListener("pointermove", onMove);
          };
          const off = handleParallax();
          if (off) return () => off();
        }
      }
    });
  }

  function play() {
    if (reducedMotion.current) {
      // show final state immediately
      if (pageRef.current) pageRef.current.style.opacity = "1";
      if (vaultRef.current) {
        vaultRef.current.style.transform = "translateY(0) scale(1)";
        vaultRef.current.style.opacity = "1";
      }
      if (rimRef.current) rimRef.current.style.opacity = "1";
      if (eyebrowRef.current) {
        eyebrowRef.current.style.transform = "translateY(0)";
        eyebrowRef.current.style.opacity = "1";
      }
      if (headlineRef.current) {
        headlineRef.current.querySelectorAll<HTMLElement>(".word").forEach(el => {
          el.style.transform = "translateY(0)";
          el.style.opacity = "1";
        });
      }
      if (bodyRef.current) {
        bodyRef.current.style.transform = "translateY(0)";
        bodyRef.current.style.opacity = "1";
      }
      if (buttonsRef.current) {
        buttonsRef.current.querySelectorAll<HTMLElement>(".hero-btn").forEach(el => {
          el.style.transform = "translateY(0)";
          el.style.opacity = "1";
        });
      }
      if (microRef.current) microRef.current.style.opacity = "1";
      if (chipsRef.current) chipsRef.current.style.opacity = "1";
      return;
    }
    build();
  }

  function pause() {
    if (ctx) {
      ctx.pause();
    }
  }

  function setProgress(p: number) {
    // hero copy fades out within first 6% of scroll; parallax unpins
    if (heroCopyRef.current && p <= 0.06) {
      const fade = 1 - Math.min(1, p / 0.06);
      heroCopyRef.current.style.opacity = String(fade);
      heroCopyRef.current.style.transform = `translateY(${-21 * (1 - fade)}px)`;
    } else if (heroCopyRef.current) {
      heroCopyRef.current.style.opacity = "1";
      heroCopyRef.current.style.transform = "translateY(0)";
    }
  }

  return { play, pause, setProgress };
}

export default createHeroTimeline;
