{"kind":"tool","id":"aokPYxBPb3w","toolName":"write_file","input":{"path":"src/components/HeroButtons.tsx","instructions":"HeroButtons.tsx — Sign up / Sign in reactions, hover, press, click, focus, reduced-motion, touch","content":"/* HeroButtons.tsx — VaultPay AI hero CTA reactions.
   Spec-driven hover/press/click/follow behaviors plus reduced-motion and touch. */

import { useRef, useEffect, useCallback } from "react";
import gsap from "gsap";
import type { RefObject } from "react";

export interface HeroButtonsProps {
  signupRef: RefObject<HTMLAnchorElement | null>;
  signinRef: RefObject<HTMLAnchorElement | null>;
  wheelRef: RefObject<HTMLElement | null>;
  keypadRef: RefObject<HTMLElement | null>;
  seamRef: RefObject<HTMLElement | null>;
  hingeRef: RefObject<HTMLElement | null>;
  rimRef: RefObject<HTMLElement | null>;
  reducedMotion: RefObject<boolean>;
  isLargeTouch: RefObject<boolean>;
  onSignUp: () => void;
  onSignIn: () => void;
  signupHref: string;
  signinHref: string;
}

export function HeroButtons({
  signupRef,
  signinRef,
  wheelRef,
  keypadRef,
  seamRef,
  hingeRef,
  rimRef,
  reducedMotion,
  isLargeTouch,
  onSignUp,
  onSignIn,
  signupHref,
  signinHref,
}: HeroButtonsProps) {
  const mountedRef = useRef(false);

  useEffect(() => {
    mountedRef.current = true;
    return () => { mountedRef.current = false; };
  }, []);

  const bindReactions = useCallback((loop: "signup" | "signin", ref: RefObject<HTMLElement | null>) => {
    if (!mountedRef.current) return;
    const el = ref.current;
    if (!el) return;

    el.addEventListener("mouseenter", () => {
      if (reducedMotion.current) return;
      if (loop === "signup") {
        if (wheelRef.current) {
          gsap.to(wheelRef.current, {
            rotation: 55,
            duration: 0.618,
            ease: "power2.out",
            overwrite: "auto",
          });
        }
        if (hingeRef.current) {
          gsap.fromTo(hingeRef.current, {
            background: "rgba(184,137,58,0.0)",
          }, {
            background: "rgba(184,137,58,0.9)",
            duration: 0.618,
            ease: "power2.out",
            overwrite: "auto",
          });
        }
        if (seamRef.current) {
          gsap.fromTo(seamRef.current, {
            stroke: "rgba(18,165,181,0.0)",
          }, {
            stroke: "rgba(230,184,103,0.55)",
            duration: 0.618,
            ease: "power2.out",
            overwrite: "auto",
          });
        }
      } else {
        if (keypadRef.current) {
          gsap.fromTo(keypadRef.current, {
            fill: "rgba(255,255,255,0.0)",
          }, {
            fill: "rgba(18,165,181,0.0)",
            duration: 0.382,
            ease: "power2.out",
            overwrite: "auto",
          });
          gsap.to(keypadRef.current, {
            boxShadow: "0 0 13px rgba(18,165,181,0.9)",
            duration: 0.382,
            ease: "power2.out",
            overwrite: "auto",
          });
        }
      }
      if (rimRef.current) {
        gsap.to(rimRef.current, {
          boxShadow: "0 0 40px rgba(18,165,181,0.25)",
          duration: 0.382,
          ease: "power2.out",
          overwrite: "auto",
        });
      }
    });

    el.addEventListener("mouseleave", () => {
      if (reducedMotion.current) return;
      if (loop === "signup") {
        if (wheelRef.current) {
          gsap.to(wheelRef.current, {
            rotation: 0,
            duration: 0.382,
            ease: "power2.out",
            overwrite: "auto",
          });
        }
        if (hingeRef.current) {
          gsap.to(hingeRef.current, {
            background: "rgba(184,137,58,0.0)",
            duration: 0.382,
            ease: "power2.out",
            overwrite: "auto",
          });
        }
        if (seamRef.current) {
          gsap.to(seamRef.current, {
            stroke: "rgba(18,165,181,0.0)",
            duration: 0.382,
            ease: "power2.out",
            overwrite: "auto",
          });
        }
      } else {
        if (keypadRef.current) {
          gsap.to(keypadRef.current, {
            fill: "rgba(255,255,255,0.0)",
            duration: 0.382,
            ease: "power2.out",
            overwrite: "auto",
          });
          gsap.to(keypadRef.current, {
            boxShadow: "0 0 0px rgba(18,165,181,0)",
            duration: 0.382,
            ease: "power2.out",
            overwrite: "auto",
          });
        }
      }
      if (rimRef.current) {
        gsap.to(rimRef.current, {
          boxShadow: "0 0 0px rgba(18,165,181,0)",
          duration: 0.382,
          ease: "power2.out",
          overwrite: "auto",
        });
      }
    });
  }, [reducedMotion, wheelRef, keypadRef, seamRef, hingeRef, rimRef]);

  useEffect(() => {
    if (!mountedRef.current) return;
    const signup = signupRef.current;
    const signin = signinRef.current;
    if (!signup || !signin) return;

    const pressHandler = (e: MouseEvent) => {
      const target = e.currentTarget as HTMLElement;
      if (reducedMotion.current) return;
      gsap.to(target, {
        scale: 0.97,
        duration: 0.236,
        ease: "power2.out",
        overwrite: "auto",
      });
    };

    const releaseHandler = (e: MouseEvent) => {
      const target = e.currentTarget as HTMLElement;
      if (reducedMotion.current) return;
      gsap.to(target, {
        scale: 1,
        duration: 0.236,
        ease: "power2.out",
        overwrite: "auto",
      });
    };

    const clickSignup = async (e: MouseEvent) => {
      e.preventDefault();
      if (reducedMotion.current) {
        onSignUp();
        return;
      }
      const btn = e.currentTarget as HTMLElement;
      // full 360 wheel
      if (wheelRef.current) {
        gsap.to(wheelRef.current, {
          rotation: 360,
          duration: 1,
          ease: "power3.inOut",
          overwrite: "auto",
        });
      }
      if (seamRef.current) {
        gsap.fromTo(seamRef.current, {
          stroke: "rgba(230,184,103,0.0)",
        }, {
          stroke: "rgba(230,184,103,0.85)",
          duration: 0.309,
          ease: "power2.out",
          yoyo: true,
          repeat: 1,
          overwrite: "auto",
        });
      }
      // route after 1s
      setTimeout(() => {
        if (!mountedRef.current) return;
        const link = signupRef.current;
        if (link) {
          link.setAttribute("href", signupHref);
          link.click();
        }
      }, 1000);
      // restore href after a tick so the click is honored
      if (signup) signup.setAttribute("href", signupHref);
    };

    const clickSignin = async (e: MouseEvent) => {
      e.preventDefault();
      if (reducedMotion.current) {
        onSignIn();
        return;
      }
      const sequence = [
        keypadRef.current,
        keypadRef.current,
        keypadRef.current,
        keypadRef.current,
      ];
      for (let i = 0; i < 4; i++) {
        await new Promise(r => setTimeout(r, 161.8));
        if (!mountedRef.current || !keypadRef.current) break;
        gsap.fromTo(keypadRef.current, {
          fill: "rgba(255,255,255,0.0)",
        }, {
          fill: "rgba(18,165,181,0.9)",
          duration: 0.1618,
          ease: "power2.out",
          overwrite: "auto",
          onComplete: () => {
            gsap.to(keypadRef.current, {
              fill: "rgba(255,255,255,0.0)",
              duration: 0.1618,
              ease: "power2.out",
              overwrite: "auto",
            });
          },
        });
      }
      if (seamRef.current) {
        gsap.fromTo(seamRef.current, {
          stroke: "rgba(18,165,181,0.0)",
        }, {
          stroke: "rgba(31,157,107,0.9)",
          duration: 0.309,
          ease: "power2.out",
          yoyo: true,
          repeat: 1,
          overwrite: "auto",
        });
      }
      setTimeout(() => {
        if (!mountedRef.current) return;
        const link = signinRef.current;
        if (link) {
          link.setAttribute("href", signinHref);
          link.click();
        }
      }, 1000);
      if (signin) signin.setAttribute("href", signinHref);
    };

    signup.addEventListener("mousedown", pressHandler);
    signup.addEventListener("mouseup", releaseHandler);
    signup.addEventListener("click", clickSignup);
    signin.addEventListener("mousedown", pressHandler);
    signin.addEventListener("mouseup", releaseHandler);
    signin.addEventListener("click", clickSignin);

    return () => {
      signup.removeEventListener("mousedown", pressHandler);
      signup.removeEventListener("mouseup", releaseHandler);
      signup.removeEventListener("click", clickSignup);
      signin.removeEventListener("mousedown", pressHandler);
      signin.removeEventListener("mouseup", releaseHandler);
      signin.removeEventListener("click", clickSignin);
    };
  }, [signupRef, signinRef, wheelRef, keypadRef, seamRef, reducedMotion, isLargeTouch, onSignUp, onSignIn, signupHref, signinHref]);

  useEffect(() => {
    if (!mountedRef.current) return;
    bindReactions("signup", signupRef);
    bindReactions("signin", signinRef);
  }, [bindReactions, signupRef, signinRef]);

  // touch taps: first tap shows reaction, second tap navigates
  useEffect(() => {
    if (!mountedRef.current || !isLargeTouch.current) return;
    const tapState = { signup: false, signin: false };
    const signup = signupRef.current;
    const signin = signinRef.current;
    const handler = (type: "signup" | "signin") => (e: MouseEvent) => {
      if (reducedMotion.current) {
        if (type === "signup") onSignUp();
        else onSignIn();
        return;
      }
      const fired = tapState[type];
      if (!fired) {
        tapState[type] = true;
        e.preventDefault();
        if (type === "signup") {
          if (wheelRef.current) gsap.to(wheelRef.current, { rotation: 55, duration: 0.618, ease: "power2.out", overwrite: "auto" });
        } else {
          if (keypadRef.current) gsap.to(keypadRef.current, { fill: "rgba(18,165,181,0.9)", duration: 0.382, ease: "power2.out", overwrite: "auto" });
        }
      } else {
        tapState[type] = false;
        if (type === "signup") {
          if (signup) signup.click();
        } else {
          if (signin) signin.click();
        }
      }
    };
    if (signup) signup.addEventListener("click", handler("signup"));
    if (signin) signin.addEventListener("click", handler("signin"));
    return () => {
      if (signup) signup.removeEventListener("click", handler("signup"));
      if (signin) signin.removeEventListener("click", handler("signin"));
    };
  }, [signupRef, signinRef, wheelRef, keypadRef, isLargeTouch, reducedMotion, onSignUp, onSignIn]);

  return null;
}
