{"kind":"tool","id":"aopCcdoQdSQ","toolName":"write_file","input":{"path":"src/styles/hero-tokens.css","instructions":"Hero tokens: colors, type, spacing, durations from the VaultPay AI hero spec","content":"/* Hero tokens — VaultPay AI landing top. Spec-driven values only. */

:root {
  /* light studio theme, sampled from frame edges */
  --hero-bg-top: #C9D0D2;
  --hero-bg-mid: #D5DBDC;
  --hero-bg-bot: #E1E7E8;

  /* type: Fraunces (display), JetBrains Mono (eyebrow/chips), Inter (body) */
  --hero-eyebrow: "JetBrains Mono", ui-monospace, monospace;
  --hero-display: "Fraunces", system-ui, sans-serif;
  --hero-body: "Inter", system-ui, sans-serif;

  /* copy sizes — base 16, x1.618 */
  --hero-step-base: 16px;
  --hero-step-0: clamp(42px, 4.7vw, 68px);   /* H1 */
  --hero-step-1: 26px;
  --hero-step-2: 42px;
  --hero-step-3: 68px;
  --hero-step-4: 110px;

  /* spacing: fibonacci 8/13/21/34/55/89 */
  --hero-s-8: 8px;
  --hero-s-13: 13px;
  --hero-s-21: 21px;
  --hero-s-34: 34px;
  --hero-s-55: 55px;
  --hero-s-89: 89px;

  /* colors */
  --hero-ink: #0E1520;
  --hero-slate: #4B5663;
  --hero-steel: #8A95A1;
  --hero-brass: #B8893A;
  --hero-brass-light: #E2B867;
  --hero-teal: #12A5B5;
  --hero-success: #1F9D6B;

  /* durations from phi set */
  --hero-d-236: 0.236s;
  --hero-d-382: 0.382s;
  --hero-d-618: 0.618s;
  --hero-d-1: 1s;
  --hero-d-1618: 1.618s;
  --hero-d-2618: 2.618s;

  /* button geometry */
  --hero-btn-h: 55px;
  --hero-btn-r: 13px;
  --hero-btn-gap: 21px;
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --hero-d-236: 0.001s;
    --hero-d-382: 0.001s;
    --hero-d-618: 0.001s;
    --hero-d-1: 0.001s;
    --hero-d-1618: 0.001s;
    --hero-d-2618: 0.001s;
  }
}
