.hero-page {
  position: relative;
  min-height: 100vh;
  background: linear-gradient(to bottom, var(--hero-bg-top), var(--hero-bg-mid) 50%, var(--hero-bg-bot));
}
.hero-page::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.04;
  background-image: repeating-radial-gradient(circle at 17% 23%, #000 0, transparent 1px, transparent 3px);
}

.hero-grid {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 38.2% 1fr;
  min-height: 100vh;
}

.hero-copy {
  padding-left: var(--hero-s-89);
  padding-right: var(--hero-s-89);
  padding-block: var(--hero-s-89);
  display: grid;
  gap: var(--hero-s-34);
  align-content: start;
  max-width: 100%;
}

.hero-eyebrow {
  font-family: var(--hero-eyebrow);
  font-size: 12px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--hero-slate);
}

.hero-h1 {
  font-family: var(--hero-display);
  font-weight: 600;
  font-optical-sizing: auto;
  font-size: var(--hero-step-0);
  line-height: 1.05;
  letter-spacing: -0.02em;
  color: var(--hero-ink);
  margin: 8px 0 0;
}
.hero-h1 .word { display: inline-block; }
.hero-h1 .vh { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap; }

.hero-body {
  font-family: var(--hero-body);
  font-weight: 400;
  font-size: var(--hero-step-base);
  line-height: 1.618;
  color: var(--hero-slate);
  max-width: 44ch;
}

.hero-cta-row {
  display: flex;
  align-items: center;
  gap: var(--hero-btn-gap);
  margin-top: var(--hero-s-21);
}
.hero-cta-row[data-largetouch="1"] .hero-btn { touch-action: manipulation; }

.hero-micro {
  font-family: var(--hero-eyebrow);
  font-size: 12px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--hero-slate);
  margin-top: var(--hero-s-13);
}

.hero-chips { display: flex; flex-wrap: wrap; gap: var(--hero-s-13); margin-top: var(--hero-s-21); }
.hero-chip {
