  font-size: 12px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--hero-slate);
  border: 1px solid var(--hero-steel);
  padding: 6px 10px;
  border-radius: 999px;
}

.hero-vault {
  position: relative;
  overflow: visible;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-frame {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  will-change: transform, opacity;
}

.hero-vault-rim {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  box-shadow: 0 0 0 1px rgba(18,165,181,0.25) inset, 0 0 40px rgba(18,165,181,0.00);
}
.hero-vault-rim[data-visible="1"] { opacity: 1; }

.hero-hotspots {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
  z-index: 2;
}
.hero-wheel { transform-box: fill-box; transform-origin: center; }
.hero-keypad { transform-box: fill-box; transform-origin: center; }
.hero-seam { transform-box: fill-box; transform-origin: center; }

