{"kind":"tool","id":"aozLoUdgK2Q","toolName":"write_file","input":{"path":"src/components/HeroVault.tsx","instructions":"HeroVault.tsx — canvas frame 1, hotspot overlay, wheel, rim, keypad, seam refs","content":"/* HeroVault.tsx — VaultPay AI hero vault: canvas frame 1 + hotspot overlay.
   Single frame drawn at contain fit; hotspot overlay is percent of drawn rect. */

import { useRef, useEffect, useCallback } from "react";

export interface HeroVaultProps {
  frameSrc?: string;
  wheelRef?: React.RefObject<HTMLElement | null>;
  rimRef?: React.RefObject<HTMLElement | null>;
  keypadRef?: React.RefObject<HTMLElement | null>;
  seamRef?: React.RefObject<HTMLElement | null>;
}

export function HeroVault({
  frameSrc = "/vault-frames/f_001.webp",
  wheelRef,
  rimRef,
  keypadRef,
  seamRef,
}: HeroVaultProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const imageRef = useRef<HTMLImageElement | null>(null);

  const fit = useCallback((imgW: number, imgH: number, w: number, h: number) => {
    const s = Math.max(w / imgW, h / imgH);
