{"kind":"tool","id":"ao0MrhfijBg","toolName":"write_file","input":{"path":"src/components/hero-timeline.ts","instructions":"Hero timeline: entrance GSAP + idle loops + scroll handoff, spec timings","content":"/* hero-timeline.ts — VaultPay AI hero entrance, idle loops, parallax, scroll handoff.
   Spec timings and behaviors only. Call play() once on mount. */

import gsap from "gsap";
import type { RefObject } from "react";

interface Refs {
  pageRef: RefObject<HTMLElement | null>;
  frameRef: RefObject<HTMLImageElement | null>;
  rimRef: RefObject<HTMLElement | null>;
  eyebrowRef: RefObject<HTMLElement | null>;
  headlineRef: RefObject<HTMLElement | null>;
  bodyRef: RefObject<HTMLElement | null>;
  buttonsRef: RefObject<HTMLElement | null>;
  chipsRef: RefObject<HTMLElement | null>;
  microRef: RefObject<HTMLElement | null>;
  vaultRef: RefObject<HTMLElement | null>;
  wheelRef: RefObject<HTMLElement | null>;
  keypadRef: RefObject<HTMLElement | null>;
  seamRef: RefObject<HTMLElement | null>;
  hingeRef: RefObject<HTMLElement | null>;
  heroCopyRef: RefObject<HTMLElement | null>;
  heroVaultRef: RefObject<HTMLElement | null>;
}

export interface HeroTimelineAPI {
  play: () => void;
  pause: () => void;
  setProgress: (p: number) => void;
}

export function createHeroTimeline(refs: Refs & { reducedMotion: RefObject<boolean>; isLargeTouch: RefObject<boolean> }) {
  let ctx: gsap.Context | null = null;
  const play = () => {
    if (refs.reducedMotion.current) {
      const { pageRef, vaultRef, rimRef, eyebrowRef, headlineRef, bodyRef, buttonsRef, microRef, chipsRef } = refs;
      if (pageRef.current) pageRef.current.style.opacity = "1";
      if (vaultRef.current) {
        vaultRef.current.style.transform = "translateY(0) scale(1)";
        vaultRef.current.style.opacity = "1";
      }
      if (rimRef.current) rimRef.current.style.opacity = "1";
      if (eyebrowRef.current) {
        eyebrowRef.current.style.transform = "translateY(0)";
        eyebrowRef.current.style.opacity = "1";
      }
      if (headlineRef.current) {
        headlineRef.current.querySelectorAll<HTMLElement>(".word").forEach(el => {
          el.style.transform = "translateY(0)";
          el.style.opacity = "1";
        });
      }
      if (bodyRef.current) {
        bodyRef.current.style.transform = "translateY(0)";
        bodyRef.current.style.opacity = "1";
      }
      if (buttonsRef.current) {
        buttonsRef.current.querySelectorAll<HTMLElement>(".hero-btn").forEach(el => {
          el.style.transform = "translateY(0)";
          el.style.opacity = "1";
        });
      }
      if (microRef.current) microRef.current.style.opacity = "1";
      if (chipsRef.current) chipsRef.current.style.opacity = "1";
      return;
    }
    ctx = gsap.context(() => {
      const { pageRef, vaultRef, rimRef, eyebrowRef, headlineRef, bodyRef, buttonsRef, microRef, chipsRef, heroCopyRef } = refs;
      const isReduced = refs.reducedMotion.current;
      const durations = {
        fast: isReduced ? 0.001 : 0.236,
        mid: isReduced ? 0.001 : 0.382,
        slow: isReduced ? 0.001 : 0.618,
        long: isReduced ? 0.001 : 1.618,
      };
      gsap.fromTo(pageRef.current, { opacity: 0 }, {
        opacity: 1,
        duration: durations.slow,
        ease: "power3.out",
        overwrite: "auto",
      });
      gsap.fromTo(vaultRef.current, { y: 34, opacity: 0, scale: 0.97 }, {
        y: 0, opacity: 1, scale: 1,
        duration: durations.long,
        ease: isReduced ? "power1.out" : "expo.out",
        overwrite: "auto",
      });
      gsap.fromTo(rimRef.current, { opacity: 0 }, {
        opacity: 1,
        duration: durations.slow,
        ease: "power2.out",
        overwrite: "auto",
      });
      gsap.fromTo(eyebrowRef.current, { y: 13, opacity: 0 }, {
        y: 0, opacity: 1,
        duration: durations.mid,
        ease: "power2.out",
        delay: 0.382,
        overwrite: "auto",
      });
      if (headlineRef.current) {
        const words = headlineRef.current.querySelectorAll<HTMLElement>(".word");
        gsap.fromTo(words, { y: 34, opacity: 0 }, {
          y: 0, opacity: 1,
          duration: durations.slow,
          ease: "power2.out",
          stagger: 0.0618,
          delay: 0.618,
          overwrite: "auto",
        });
      }
      gsap.fromTo(bodyRef.current, { y: 21, opacity: 0 }, {
        y: 0, opacity: 1,
        duration: durations.slow,
        ease: "power2.out",
        delay: 1.000,
        overwrite: "auto",
      });
      if (buttonsRef.current) {
        const items = buttonsRef.current.querySelectorAll<HTMLElement>(".hero-btn");
        gsap.fromTo(items, { y: 21, opacity: 0 }, {
          y: 0, opacity: 1,
          duration: durations.slow,
          ease: "power2.out",
          stagger: 0.236,
          delay: 1.382,
          overwrite: "auto",
        });
      }
      const tail = [microRef.current, chipsRef.current].filter(Boolean);
      if (tail.length) {
        gsap.fromTo(tail, { opacity: 0 }, {
          opacity: 1,
          duration: durations.slow,
          ease: "power2.out",
          stagger: 0.1,
          delay: 1.618,
          overwrite: "auto",
        });
      }
      if (!isReduced && !refs.reducedMotion.current) {
        const float = { y: 0 };
        gsap.to(float, {
          y: 8,
          duration: 3.09,
          ease: "sine.inOut",
          repeat: -1,
          yoyo: true,
        });
        gsap.to(vaultRef.current, {
          y: () => float.y,
          duration: 0.001,
          overwrite: "auto",
        });
        if (refs.wheelRef.current) {
          gsap.to(refs.wheelRef.current, {
            opacity: 0.6,
            duration: 1.309,
            ease: "sine.inOut",
            repeat: -1,
            yoyo: true,
            overwrite: "auto",
          });
        }
      }
    });
  };

  const pause = () => {
    if (ctx) ctx.pause();
  };

  const setProgress = (p: number) => {
    const { heroCopyRef } = refs;
    if (!heroCopyRef.current) return;
    if (p <= 0.06) {
      const fade = 1 - Math.min(1, p / 0.06);
      heroCopyRef.current.style.opacity = String(fade);
      heroCopyRef.current.style.transform = `translateY(${-21 * (1 - fade)}px)`;
    } else {
      heroCopyRef.current.style.opacity = "1";
      heroCopyRef.current.style.transform = "translateY(0)";
    }
  };

  return { play, pause, setProgress };
}

export default createHeroTimeline;
"}}


{"kind":"tool","id":"ao1g1DwA52s","toolName":"write_file","input":{"path":"src/components/HeroButtons.tsx","instructions":"HeroButtons.tsx — Sign up / Sign in reactions plus reduced motion and touch routing","content":"/* HeroButtons.tsx — VaultPay AI hero CTA reactions.
   Spec-driven hover/press/click/follow behaviors plus reduced-motion and touch. */

import { useRef, useEffect, useCallback } from "react";
import gsap from "gsap";
import type { RefObject } from "react";

export interface HeroButtonsProps {
  signupRef: RefObject<HTMLAnchorElement | null>;
  signinRef: RefObject<HTMLAnchorElement | null>;
  wheelRef: RefObject<HTMLElement | null>;
  keypadRef: RefObject<HTMLElement | null>;
  seamRef: RefObject<HTMLElement | null>;
  hingeRef: RefObject<HTMLElement | null>;
  rimRef: RefObject<HTMLElement | null>;
  reducedMotion: RefObject<boolean>;
  isLargeTouch: RefObject<boolean>;
  onSignUp: () => void;
  onSignIn: () => void;
  signupHref: string;
  signinHref: string;
}

export function HeroButtons({
  signupRef,
  signinRef,
  wheelRef,
  keypadRef,
  seamRef,
  hingeRef,
  rimRef,
  reducedMotion,
  isLargeTouch,
  onSignUp,
  onSignIn,
  signupHref,
  signinHref,
}: HeroButtonsProps) {
  const mountedRef = useRef(false);

  useEffect(() => { mountedRef.current = true; return () => { mountedRef.current = false; }; }, []);

  const enterLeave = useCallback((type: "signup" | "signin") => (e: MouseEvent) => {
    if (reducedMotion.current) return;
    const btn = e.currentTarget as HTMLElement;
    if (type === "signup") {
      if (wheelRef.current) gsap.to(wheelRef.current, { rotation: 55, duration: 0.618, ease: "power2.out", overwrite: "auto" });
      if (hingeRef.current) gsap.to(hingeRef.current, { background: "rgba(184,137,58,0.9)", duration: 0.618, ease: "power2.out", overwrite: "auto" });
      if (seamRef.current) gsap.to(seamRef.current, { stroke: "rgba(230,184,103,0.55)", duration: 0.618, ease: "power2.out", overwrite: "auto" });
    } else {
      if (keypadRef.current) {
        gsap.to(keypadRef.current, { fill: "rgba(18,165,181,0.9)", duration: 0.382, ease: "power2.out", overwrite: "auto" });
        gsap.to(keypadRef.current, { boxShadow: "0 0 13px rgba(18,165,181,0.9)", duration: 0.382, ease: "power2.out", overwrite: "auto" });
      }
    }
    if (rimRef.current) gsap.to(rimRef.current, { boxShadow: "0 0 40px rgba(18,165,181,0.25)", duration: 0.382, ease: "power2.out", overwrite: "auto" });
  }, [wheelRef, hingeRef, seamRef, keypadRef, rimRef, reducedMotion]);

  const leave = useCallback((type: "signup" | "signin") => (e: MouseEvent) => {
    if (reducedMotion.current) return;
    const btn = e.currentTarget as HTMLElement;
    if (type === "signup") {
      if (wheelRef.current) gsap.to(wheelRef.current, { rotation: 0, duration: 0.382, ease: "power2.out", overwrite: "auto" });
      if (hingeRef.current) gsap.to(hingeRef.current, { background: "rgba(184,137,58,0.0)", duration: 0.382, ease: "power2.out", overwrite: "auto" });
      if (seamRef.current) gsap.to(seamRef.current, { stroke: "rgba(18,165,181,0.0)", duration: 0.382, ease: "power2.out", overwrite: "auto" });
    } else {
      if (keypadRef.current) {
        gsap.to(keypadRef.current, { fill: "rgba(255,255,255,0.0)", duration: 0.382, ease: "power2.out", overwrite: "auto" });
        gsap.to(keypadRef.current, { boxShadow: "0 0 0px rgba(18,165,181,0)", duration: 0.382, ease: "power2.out", overwrite: "auto" });
      }
    }
    if (rimRef.current) gsap.to(rimRef.current, { boxShadow: "0 0 0px rgba(18,165,181,0)", duration: 0.382, ease: "power2.out", overwrite: "auto" });
  }, [wheelRef, hingeRef, seamRef, keypadRef, rimRef, reducedMotion]);

  useEffect(() => {
    if (!mountedRef.current) return;
    const signup = signupRef.current;
    const signin = signinRef.current;
    if (!signup || !signin) return;
    const press = (target: HTMLElement) => gsap.to(target, { scale: 0.97, duration: 0.236, ease: "power2.out", overwrite: "auto" });
    const release = (target: HTMLElement) => gsap.to(target, { scale: 1, duration: 0.236, ease: "power2.out", overwrite: "auto" });
    const clickSignup = (e: MouseEvent) => {
      e.preventDefault();
      if (reducedMotion.current) { onSignUp(); return; }
      if (wheelRef.current) gsap.to(wheelRef.current, { rotation: 360, duration: 1, ease: "power3.inOut", overwrite: "auto" });
      if (seamRef.current) gsap.to(seamRef.current, { stroke: "rgba(230,184,103,0.85)", duration: 0.309, ease: "power2.out", yoyo: true, repeat: 1, overwrite: "auto" });
      setTimeout(() => {
        if (!mountedRef.current) return;
        const link = signupRef.current;
        if (link) { link.setAttribute("href", signupHref); link.click(); }
      }, 1000);
      if (signup) signup.setAttribute("href", signupHref);
    };
    const clickSignin = (e: MouseEvent) => {
      e.preventDefault();
      if (reducedMotion.current) { onSignIn(); return; }
      (async () => {
        for (let i = 0; i < 4; i++) {
          await new Promise(r => setTimeout(r, 161.8));
          if (!mountedRef.current || !keypadRef.current) break;
          gsap.fromTo(keypadRef.current, { fill: "rgba(255,255,255,0.0)" }, {
            fill: "rgba(18,165,181,0.9)",
            duration: 0.1618,
            ease: "power2.out",
            overwrite: "auto",
            onComplete: () => { gsap.to(keypadRef.current, { fill: "rgba(255,255,255,0.0)", duration: 0.1618, ease: "power2.out", overwrite: "auto" }); },
          });
        }
        if (seamRef.current) gsap.to(seamRef.current, { stroke: "rgba(31,157,107,0.9)", duration: 0.309, ease: "power2.out", yoyo: true, repeat: 1, overwrite: "auto" });
        setTimeout(() => {
          if (!mountedRef.current) return;
          const link = signinRef.current;
          if (link) { link.setAttribute("href", signinHref); link.click(); }
        }, 1000);
        if (signin) signin.setAttribute("href", signinHref);
      })();
    };
    signup.addEventListener("mousedown", (e) => press(e.currentTarget as HTMLElement));
    signup.addEventListener("mouseup", (e) => release(e.currentTarget as HTMLElement));
    signup.addEventListener("click", clickSignup);
    signin.addEventListener("mousedown", (e) => press(e.currentTarget as HTMLElement));
    signin.addEventListener("mouseup", (e) => release(e.currentTarget as HTMLElement));
    signin.addEventListener("click", clickSignin);
    signup.addEventListener("mouseenter", enterLeave("signup"));
    signup.addEventListener("mouseleave", leave("signup"));
    signin.addEventListener("mouseenter", enterLeave("signin"));
    signin.addEventListener("mouseleave", leave("signin"));
    return () => {
      signup.removeEventListener("mousedown", (e) => press(e.currentTarget as HTMLElement));
      signup.removeEventListener("mouseup", (e) => release(e.currentTarget as HTMLElement));
      signup.removeEventListener("click", clickSignup);
      signin.removeEventListener("mousedown", (e) => press(e.currentTarget as HTMLElement));
      signin.removeEventListener("mouseup", (e) => release(e.currentTarget as HTMLElement));
      signin.removeEventListener("click", clickSignin);
      signup.removeEventListener("mouseenter", enterLeave("signup"));
      signup.removeEventListener("mouseleave", leave("signup"));
      signin.removeEventListener("mouseenter", enterLeave("signin"));
      signin.removeEventListener("mouseleave", leave("signin"));
    };
  }, [signupRef, signinRef, wheelRef, keypadRef, seamRef, hingeRef, rimRef, reducedMotion, isLargeTouch, onSignUp, onSignIn, signupHref, signinHref]);

  useEffect(() => {
    if (!mountedRef.current || !isLargeTouch.current) return;
    const tap = { signup: false, signin: false };
    const signup = signupRef.current;
    const signin = signinRef.current;
    const handler = (type: "signup" | "signin") => (e: MouseEvent) => {
      if (reducedMotion.current) { if (type === "signup") onSignUp(); else onSignIn(); return; }
      const used = tap[type];
      if (!used) {
        tap[type] = true;
        e.preventDefault();
        if (type === "signup" && wheelRef.current) gsap.to(wheelRef.current, { rotation: 55, duration: 0.618, ease: "power2.out", overwrite: "auto" });
        if (type === "signin" && keypadRef.current) gsap.to(keypadRef.current, { fill: "rgba(18,165,181,0.9)", duration: 0.382, ease: "power2.out", overwrite: "auto" });
      } else {
        tap[type] = false;
        if (type === "signup") signup?.click();
        else signin?.click();
      }
    };
    if (signup) signup.addEventListener("click", handler("signup"));
    if (signin) signin.addEventListener("click", handler("signin"));
    return () => {
      if (signup) signup.removeEventListener("click", handler("signup"));
      if (signin) signin.removeEventListener("click", handler("signin"));
    };
  }, [signupRef, signinRef, wheelRef, keypadRef, isLargeTouch, reducedMotion, onSignUp, onSignIn]);

  return null;
}
