+/* hero-timeline.ts — VaultPay AI hero entrance, idle loops, parallax, scroll handoff.
+   Spec timings and behaviors only. Call play() once on mount. */
+
+import gsap from "gsap";
+import type { RefObject } from "react";
+
+interface Refs {
+  pageRef: RefObject<HTMLElement | null>;
+  frameRef: RefObject<HTMLImageElement | null>;
+  rimRef: RefObject<HTMLElement | null>;
+  eyebrowRef: RefObject<HTMLElement | null>;
+  headlineRef: RefObject<HTMLElement | null>;
+  bodyRef: RefObject<HTMLElement | null>;
+  buttonsRef: RefObject<HTMLElement | null>;
+  chipsRef: RefObject<HTMLElement | null>;
+  microRef: RefObject<HTMLElement | null>;
+  vaultRef: RefObject<HTMLElement | null>;
+  wheelRef: RefObject<HTMLElement | null>;
+  keypadRef: RefObject<HTMLElement | null>;
+  seamRef: RefObject<HTMLElement | null>;
+  hingeRef: RefObject<HTMLElement | null>;
+  heroCopyRef: RefObject<HTMLElement | null>;
+  heroVaultRef: RefObject<HTMLElement | null>;
+}
+
+export interface HeroTimelineAPI {
+  play: () => void;
+  pause: () => void;
+  setProgress: (p: number) => void;
+}
+
+export function createHeroTimeline(refs: Refs & { reducedMotion: RefObject<boolean>; isLargeTouch: RefObject<boolean> }) {
+  let ctx: gsap.Context | null = null;
+  const play = () => {
+    if (refs.reducedMotion.current) {
+      const { pageRef, vaultRef, rimRef, eyebrowRef, headlineRef, bodyRef, buttonsRef, microRef, chipsRef } = refs;
+      if (pageRef.current) pageRef.current.style.opacity = "1";
+      if (vaultRef.current) {
+        vaultRef.current.style.transform = "translateY(0) scale(1)";
+        vaultRef.current.style.opacity = "1";
+      }
+      if (rimRef.current) rimRef.current.style.opacity = "1";
+      if (eyebrowRef.current) {
+        eyebrowRef.current.style.transform = "translateY(0)";
+        eyebrowRef.current.style.opacity = "1";
+      }
+      if (headlineRef.current) {
+        headlineRef.current.querySelectorAll<HTMLElement>(".word").forEach(el => {
+          el.style.transform = "translateY(0)";
+          el.style.opacity = "1";
+        });
+      }
+      if (bodyRef.current) {
+        bodyRef.current.style.transform = "translateY(0)";
+        bodyRef.current.style.opacity = "1";
+      }
+      if (buttonsRef.current) {
+        buttonsRef.current.querySelectorAll<HTMLElement>(".hero-btn").forEach(el => {
+          el.style.transform = "translateY(0)";
+          el.style.opacity = "1";
+        });
+      }
+      if (microRef.current) microRef.current.style.opacity = "1";
+      if (chipsRef.current) chipsRef.current.style.opacity = "1";
+      return;
+    }
+    ctx = gsap.context(() => {
+      const { pageRef, vaultRef, rimRef, eyebrowRef, headlineRef, bodyRef, buttonsRef, microRef, chipsRef, heroCopyRef } = refs;
+      const isReduced = refs.reducedMotion.current;
+      const durations = {
+        fast: isReduced ? 0.001 : 0.236,
+        mid: isReduced ? 0.001 : 0.382,
+        slow: isReduced ? 0.001 : 0.618,
+        long: isReduced ? 0.001 : 1.618,
+      };
+      gsap.fromTo(pageRef.current, { opacity: 0 }, {
+        opacity: 1,
+        duration: durations.slow,
