}
.stepper-rail-draw {
  opacity: 0;
}

.stepper-list {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 55px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.stepper-step {
  display: grid;
  grid-template-columns: 13px 1fr;
  column-gap: 13px;
  align-items: start;
}

.stepper-node {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  width: 13px;
  height: 13px;
  margin-top: 2px;
  box-sizing: border-box;
  border: 1px solid var(--hero-steel);
  border-radius: 50%;
  background: var(--hero-bg-mid);
  color: #fff;
}
.stepper-node svg {
  width: 8px;
  height: 8px;
}
.stepper-step[data-state="active"] .stepper-node {
  border-color: var(--hero-brass);
  backg [… 1,165 characters omitted] margin-left: 3.5px;
  border-radius: 50%;
  background: var(--hero-brass);
  box-shadow: 0 0 13px rgba(184, 137, 58, 0.7);
  animation: stepper-pulse 1.618s ease-in-out infinite;
}
@keyframes stepper-pulse {
  0%, 100% { opacity: 0.35; transform: scale(0.75); }
  50% { opacity: 1; transform: scale(1); }
}

/* ---------- compact row (under 1100px) ---------- */
.stepper-compact-row {
  display: grid;
