{"kind":"tool","id":"bym9gnTaIwQ","toolName":"write_file","input":{"path":"scripts/signup-back-repro.mjs","instructions":"Add a temporary repro script that walks the role/back/back sequence and dumps panel state.","content":"/* signup-back-repro.mjs — temporary: walk role -> Change role -> role -> Change
   role at both patient and fast speed and dump what the card is left showing. */

import { chromium } from "playwright";

const URL = (process.env.URL ?? "http://127.0.0.1:5173/").replace(/\/$/, "");

const dump = () => ({
  path: location.pathname,
  roles: document.querySelectorAll(".role-btn").length,
  roleOpacity: [...document.querySelectorAll(".role-btn")].map((b) => getComputedStyle(b).opacity),
  panel: (() => {
    const p = document.querySelector(".signup-panel");
    if (!p) return null;
    const cs = getComputedStyle(p);
    const b = p.getBoundingClientRect();
    return {
      cls: p.className,
      inline: p.getAttribute("style"),
      opacity: cs.opacity,
      transform: cs.transform,
      h: +b.height.toFixed(1),
      kids: [...p.children].map((c) => c.className),
      text: p.textContent?.trim().slice(0, 80),
    };
  })(),
  head: (() => {
    const h = document.querySelector(".signup-head");
    return h ? { inline: h.getAttribute("style"), cs: getComputedStyle(h).opacity } : null;
  })(),
  chip: !!document.querySelector('[data-testid="signup-change-role"]'),
  foot: !!document.querySelector(".signup-foot"),
  submit: !!document.querySelector('[data-testid="signup-submit"]'),
});

const browser = await chromium.launch();
const errors = [];

async function run(label, gap) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 });
  page.on("pageerror", (e) => errors.push(`${label}: ${String(e)}`));
  page.on("console", (m) => {
    if (m.type() === "error") errors.push(`${label}: console ${m.text()}`);
  });
  await page.goto(`${URL}/signup`, { waitUntil: "networkidle" });
  await page.waitForTimeout(1200);
  const log = { label, steps: [] };

  const click = async (sel, name) => {
    await page.click(sel);
    await page.waitForTimeout(gap);
    log.steps.push({ name, ...(await page.evaluate(dump)) });
  };

  log.steps.push({ name: "load", ...(await page.evaluate(dump)) });
  await click('[data-testid="role-freelancer"]', "pick freelancer");
  await click('[data-testid="signup-change-role"]', "change role");
  await click('[data-testid="role-client"]', "pick client");
  await click('[data-testid="signup-change-role"]', "change role 2");
  await page.waitForTimeout(1200);
  log.steps.push({ name: "settled", ...(await page.evaluate(dump)) });

  /* and one more round, from the settled state */
  await click('[data-testid="role-client"]', "pick client again");
  await click('[data-testid="signup-change-role"]', "change role 3");
  await page.waitForTimeout(1200);
  log.steps.push({ name: "settled 2", ...(await page.evaluate(dump)) });

  await page.close();
  return log;
}

const out = [];
out.push(await run("patient 1200", 1200));
out.push(await run("fast 80", 80));
out.push(await run("human 420", 420));

console.log(JSON.stringify({ out, errors }, null, 2));
await browser.close();
"}}


