  const vis = (sel) => {
    const el = document.querySelector(sel);
    if (!el) return "absent";
    const cs = getComputedStyle(el);
    const b = el.getBoundingClientRect();
    return `${cs.opacity} ${b.width.toFixed(0)}x${b.height.toFixed(0)}`;
  };
  return {
    path: location.pathname,
    step: document.querySelector(".signup-form")
      ? "form"
      : document.querySelector(".signup-done")
        ? "done"
        : document.querySelector(".signup-roles")
          ? "roles"
          : "none",
    roleBtns: document.querySelectorAll(".role-btn").length,
    chip: !!document.querySelector('[data-testid="signup-change-role"]'),
    card: vis(".signup-card"),
    heroSignup: vis('[data-testid="hero-signup"]'),
    heroSignin: vis('[data-testid="hero-signin"]'),
    heroH1: vis(".hero-h1"),
    ghosts: document.querySelectorAll(".scene-ghost").length,
    vaultX: getComputedStyle(document.querySelector(".vault-shift")).getPropertyValue("--vault-x").trim(),
    bodyKids: document.body.children.length,
  };
};

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 });
