    return cs.display !== "none" && cs.visibility !== "hidden" && Number(cs.opacity) > 0.01 && r.width > 1 && r.height > 1;
  });
  return {
    step: document.querySelector(".signup-form")
      ? "form"
      : document.querySelector(".signup-done")
        ? "done"
        : document.querySelector(".signup-roles")
          ? "roles"
          : "none",
    panelOpacity: panel ? Number(getComputedStyle(panel).opacity).toFixed(2) : null,
    panelInline: panel?.getAttribute("style") ?? null,
    clickable: shown.map((b) => b.getAttribute("data-testid") ?? b.className.split(" ")[0]),
    cardH: document.querySelector(".signup-card")?.getBoundingClientRect().height.toFixed(0),
    cardOpacity: document.querySelector(".signup-card") ? getComputedStyle(document.querySelector(".signup-card")).opacity : null,
  };
};

const browser = await chromium.launch();
const bad = [];
