    '[data-testid="signup-change-role"]',
  ];
  const seq = [];
  let rnd = seed * 2654435761 + 12345;
  const next = () => {
    rnd = (rnd * 1103515245 + 12345) & 0x7fffffff;
    return rnd / 0x7fffffff;
  };

  for (let i = 0; i < 6; i++) {
    const sel = sels[Math.floor(next() * sels.length)];
    const gap = 40 + Math.floor(next() * 900);
    seq.push(`${sel.split('"')[1]}@${gap}`);
    try {
      await page.click(sel, { timeout: 350, force: true });
