{"kind":"tool","id":"bzWYKgiS3nc","toolName":"write_file","input":{"path":"scripts/hero-back-inspect.mjs","instructions":"Add a temporary gsap inspection script for the hero return path.","content":"/* hero-back-inspect.mjs — temporary: hero -> /signup -> Back, then interrogate
   gsap about the tweens that touch the copy. */

import { chromium } from "playwright";

const URL = (process.env.URL ?? "http://127.0.0.1:5173/").replace(/\/$/, "");

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 });
page.on("pageerror", (e) => console.log("PAGEERROR", String(e).slice(0, 200)));
page.on("console", (m) => {
  const t = m.text();
  if (t.startsWith("[hero-back]") || t.startsWith("[move]")) console.log("   log:", t.slice(0, 300));
});

await page.goto(URL, { waitUntil: "networkidle" });
await page.waitForTimeout(10000);
await page.click('[data-testid="hero-signup"]');
await page.waitForFunction(() => location.pathname === "/signup", null, { timeout: 10000 });
await page.waitForTimeout(2600);
await page.click('[data-testid="signup-back"]');
await page.waitForFunction(() => location.pathname === "/", null, { timeout: 10000 });
await page.waitForTimeout(4000);

console.log(
  JSON.stringify(
    await page.evaluate(() => {
      const gsap = window.__gsap;
      const sel = [".hero-eyebrow", ".hero-h1", ".hero-cta-block", ".hero-micro", ".hero-body", ".hero-chips"];
      const describe = (t) => ({
        targets: (t.targets?.() ?? []).map((e) => e.className?.split(" ")[0] ?? e),
        vars: Object.fromEntries(Object.entries(t.vars ?? {}).filter(([k]) => k !== "onComplete")),
        progress: +t.progress().toFixed(3),
        paused: t.paused(),
        active: t.isActive?.() ?? null,
      });
      const out = { per: {} };
      for (const s of sel) {
        const el = document.querySelector(s);
        out.per[s] = gsap.getTweensOf(el).map(describe);
      }
      out.global = gsap.globalTimeline
        .getChildren(true)
        .filter((c) => c.targets)
        .map(describe)
        .filter((c) => c.targets.some((t) => String(t).includes("hero")));
      out.styles = Object.fromEntries(
        sel.map((s) => {
          const el = document.querySelector(s);
          return [s, `${getComputedStyle(el).opacity} | ${el.getAttribute("style")}`];
        })
      );
      return out;
    }),
    null,
    1
  )
);
await browser.close();
"}}


