/* Capture the "Pay for" crop of the hero H1 at 1440px, 2x pixel ratio (200% zoom),
   and report the glyph metrics that the letter-shape change can move. */
import { chromium } from "@playwright/test";
import fs from "node:fs";

const tag = process.argv[2] || "before";
const out = `docs/hero-shots/h1-lettershapes/${tag}-1440.png`;
fs.mkdirSync("docs/hero-shots/h1-lettershapes", { recursive: true });

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 2 });
const fontReqs = [];
page.on("response", (r) => {
  const u = r.url();
  if (/\/fonts\/.*woff2?/.test(u)) fontReqs.push(`${r.status()} ${u.replace("http://localhost:5173", "")}`);
});
await page.goto("http://localhost:5173/", { waitUntil: "load" });
await page.evaluate(() => document.fonts.ready);
await page.waitForTimeout(1800); // let the entrance timeline settle

const metrics = await page.evaluate(() => {
  const h1 = document.querySelector(".hero-h1");
  const cs = getComputedStyle(h1);
  const words = [...h1.querySelectorAll(".word")].map((w) => {
    const r = w.getBoundingClientRect();
    return { t: w.textContent, x: +r.x.toFixed(2), y: +r.y.toFixed(2), w: +r.width.toFixed(2) };
  });
  const lines = [...new Set(words.map((w) => Math.round(w.y)))];
  return {
    font: cs.fontFamily,
    size: cs.fontSize,
    weight: cs.fontWeight,
    letterSpacing: cs.letterSpacing,
    ligatures: cs.fontVariantLigatures,
    featureSettings: cs.fontFeatureSettings,
    variationSettings: cs.fontVariationSettings,
    opticalSizing: cs.fontOpticalSizing,
    lineCount: lines.length,
    lines: lines.map((y) => words.filter((w) => Math.round(w.y) === y).map((w) => w.t).join(" ")),
    box: { w: +h1.getBoundingClientRect().width.toFixed(2), h: +h1.getBoundingClientRect().height.toFixed(2) },
  };
});

// the crop: the first two word boxes, i.e. "Pay for"
const clip = await page.evaluate(() => {
  const ws = [...document.querySelectorAll(".hero-h1 .word")].slice(0, 2);
  const rs = ws.map((w) => w.getBoundingClientRect());
  const x = Math.min(...rs.map((r) => r.x)) - 6;
  const y = Math.min(...rs.map((r) => r.top)) - 8;
  const right = Math.max(...rs.map((r) => r.right)) + 6;
  const bottom = Math.max(...rs.map((r) => r.bottom)) + 8;
  return { x, y, width: right - x, height: bottom - y };
});
await page.screenshot({ path: out, clip });

console.log(tag, JSON.stringify({ ...metrics, fontRequests: fontReqs }, null, 1));
console.log("crop", JSON.stringify({ ...clip, file: out, px: `${Math.round(clip.width * 2)}x${Math.round(clip.height * 2)} @2x` }));
await browser.close();
