{"kind":"tool","id":"ee15DQCN18U","toolName":"write_file","input":{"path":"src\\lib\\clipWorker.ts","instructions":"Add a worker that fetches and decodes clip frames off the main thread.","content":"/* clipWorker.ts — fetches the clip's frames and decodes them off the main thread.

   createImageBitmap() decodes on whatever thread calls it, and on the main thread
   a batch of 1920x1080 frames takes long enough to starve the animation loop it
   is meant to feed. Doing it here keeps the playhead on time: the worker holds
   the compressed bytes (a few MB for a clip), decodes on request and transfers
   the bitmaps over, so the main thread only draws. */

type Request =
  | { type: "init"; urls: string[] }
  | { type: "decode"; index: number };

export type Reply =
  | { type: "fetched"; index: number; ok: boolean }
  | { type: "frame"; index: number; bitmap: ImageBitmap }
  | { type: "decode-failed"; index: number };

const FETCH_BATCH = 8;

let urls: string[] = [];
let blobs: (Blob | null)[] = [];
let got: boolean[] = [];
let fetching: Promise<void> | null = null;
let decoding = new Set<number>();

const post = (reply: Reply, transfer?: Transferable[]) => {
  (self as unknown as Worker).postMessage(reply, transfer ?? []);
};

const getBlob = async (i: number): Promise<Blob | null> => {
  if (got[i]) return blobs[i];
  try {
    const res = await fetch(urls[i], { cache: "force-cache" });
    if (!res.ok) throw new Error(String(res.status));
    blobs[i] = await res.blob();
  } catch {
    /* a single bad frame leaves a hold, not a failed clip */
    blobs[i] = null;
  } finally {
    got[i] = true;
    post({ type: "fetched", index: i, ok: blobs[i] !== null });
  }
  return blobs[i];
};

/* frame 0 first so the clip is drawable, then the rest streams in */
const fetchAll = () => {
  if (fetching) return fetching;
  fetching = (async () => {
    if (!urls.length) return;
    await getBlob(0);
    for (let i = 1; i < urls.length; i += FETCH_BATCH) {
      const batch: Promise<Blob | null>[] = [];
      for (let k = i; k < Math.min(i + FETCH_BATCH, urls.length); k++) batch.push(getBlob(k));
      await Promise.all(batch);
    }
  })();
  return fetching;
};

self.onmessage = async (e: MessageEvent<Request>) => {
  const msg = e.data;
  if (msg.type === "init") {
    urls = msg.urls;
    blobs = new Array<Blob | null>(urls.length).fill(null);
    got = new Array<boolean>(urls.length).fill(false);
    fetching = null;
    decoding = new Set();
    void fetchAll();
    return;
  }
  if (msg.type === "decode") {
    const i = msg.index;
    if (decoding.has(i)) return;
    decoding.add(i);
    try {
      let blob = got[i] ? blobs[i] : null;
      if (!got[i]) blob = await getBlob(i);
      if (!blob) {
        post({ type: "decode-failed", index: i });
        return;
      }
      const bitmap = await createImageBitmap(blob);
      post({ type: "frame", index: i, bitmap }, [bitmap]);
    } catch {
      post({ type: "decode-failed", index: i });
    } finally {
      decoding.delete(i);
    }
  }
};
