      path: location.pathname,
      pad: p?.dataset.frame ?? null,
      padOp: p ? Number(getComputedStyle(p).opacity).toFixed(2) : null,
      wheel: w?.dataset.frame ?? null,
      wheelOp: w ? Number(getComputedStyle(w).opacity).toFixed(2) : null,
    };
  });

const watch = async (page, ms, every = 400) => {
  const out = [];
  for (let t = 0; t < ms; t += every) {
    await page.waitForTimeout(every);
    const s = await state(page);
    out.push(`${(t + every) / 1000}s pad=${s.pad}@${s.padOp} wheel=${s.wheel}@${s.wheelOp} ${s.path}`);
  }
  console.log(out.join("\n"));
};

/* 1. the automatic sequence */
{
