      "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1",
  });
  const page = await ctx.newPage();
  await page.goto(APP, { waitUntil: "load" });
  await page.waitForTimeout(16000);
  return { ctx, page };
};

const state = (page) =>
  page.evaluate(() => {
    const p = document.querySelector('[data-testid="keypad-clip"]');
    const w = document.querySelector('[data-testid="wheel-clip"]');
    return {
      path: location.pathname,
      pad: p?.dataset.frame ?? null,
      wheel: w?.dataset.frame ?? null,
    };
  });

for (const [label, sel, key] of [
  ["sign up", ".hero-btn.primary", "wheel"],
  ["sign in", ".hero-btn.glass", "pad"],
]) {
  const { ctx, page } = await open();
  const box = await page.locator(sel).boundingBox();
  const t0 = Date.now();
  await page.touchscreen.tap(box.x + box.width / 2, box.y + box.height / 2);
  const rows = [];
  for (let i = 0; i < 24; i++) {
    await page.waitForTimeout(250);
    const s = await state(page);
    rows.push(`${(Date.now() - t0) / 1000}s ${key}=${s[key]} ${s.path}`);
    if (s.path !== "/") break;
  }
  console.log(`== ${label} ==\n` + rows.join("\n"));
  await ctx.close();
}

await browser.close();
