import { chromium } from "@playwright/test";

const APP = process.env.APP_URL ?? "http://localhost:5173/";
const browser = await chromium.launch();

const open = async () => {
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await ctx.newPage();
  const errs = [];
  page.on("pageerror", (e) => errs.push(e.message));
  await page.goto(APP, { waitUntil: "load" });
  await page.waitForTimeout(17000);
  return { ctx, page, errs };
};

const frame = (page, which) =>
  page.evaluate((w) => {
    const c = document.querySelector(`[data-testid="${w}-clip"]`);
    return { frame: c?.dataset.frame ?? null, opacity: c ? Number(getComputedStyle(c).opacity).toFixed(2) : null };
  }, which);

/* hover Sign up */
{
  const { ctx, page, errs } = await open();
  await page.hover(".hero-btn.primary");
  await page.waitForTimeout(1200);
  console.log("hover sign up:", await frame(page, "wheel"));
  await page.waitForTimeout(2000);
  console.log("hover sign up settled:", await frame(page, "wheel"));
  await page.locator(".hero-btn.primary").click();
  await page.waitForTimeout(6000);
  console.log("click sign up ->", new URL(page.url()).pathname, errs);
  await ctx.close();
}

/* hover Sign in */
{
  const { ctx, page, errs } = await open();
  await page.hover(".hero-btn.glass");
  await page.waitForTimeout(1500);
  console.log("hover sign in:", await frame(page, "keypad"));
  await page.locator(".hero-btn.glass").click();
  await page.waitForTimeout(6000);
  console.log("click sign in ->", new URL(page.url()).pathname, errs);
  await ctx.close();
}

await browser.close();
"}}


