   the same hold, chip, toast and buttons without copying them. Block-level
   parse: dashboard.css has no nesting, so prelude + brace body is enough. */
import fs from "node:fs";

const DASH = "src/styles/dashboard.css";
const SHARED = "src/styles/shared.css";

const css = fs.readFileSync(DASH, "utf8");

/** split a stylesheet into top-level blocks: { prelude, text } (comments kept in prelude) */
function blocks(src) {
  const out = [];
  let i = 0;
  let start = 0;
  let depth = 0;
  let inComment = false;
  while (i < src.length) {
    const c = src[i];
    const n = src[i + 1];
    if (!inComment && c === "/" && n === "*") {
      inComment = true;
      i += 2;
      continue;
    }
    if (inComment) {
      if (c === "*" && n === "/") {
        inComment = false;
        i += 2;
        continue;
      }
      i++;
      continue;
    }
    if (c === "{") depth++;
    else if (c === "}") {
      depth--;
      if (depth === 0) {
        out.push({ start, end: i + 1, text: src.slice(start, i + 1) });
        start = i + 1;
      }
    }
    i++;
  }
  if (start < src.length) out.push({ start, end: src.length, text: src.slice(start), atRule: true });
  return out;
}

