{"kind":"tool","id":"lOKje3Ui8AE","toolName":"write_file","input":{"path":".tmp-band-probe.mjs","instructions":"Temporary script: before screenshots plus per-column colour sampling to locate the pale band.","content":"import { chromium } from "@playwright/test";
import fs from "node:fs";

const URL = "http://127.0.0.1:5199/";
const SHOTS = "docs/hero-shots/headline";
fs.mkdirSync(SHOTS, { recursive: true });

const sizes = [[1920, 1080], [1440, 900]];

const browser = await chromium.launch();
for (const [w, h] of sizes) {
  const page = await browser.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 });
  await page.goto(URL, { waitUntil: "networkidle" });
  await page.waitForTimeout(4500);
  const file = `${SHOTS}/before-${w}x${h}.png`;
  await page.screenshot({ path: file });

  /* sample the screenshot through a canvas: mean colour per column band */
  const b64 = fs.readFileSync(file).toString("base64");
  const probe = await browser.newPage();
  await probe.setContent("<canvas id=c></canvas>");
  const cols = await probe.evaluate(async (dataUrl) => {
    const img = new Image();
    img.src = dataUrl;
    await img.decode();
    const c = document.getElementById("c");
    c.width = img.width;
    c.height = img.height;
    const ctx = c.getContext("2d");
    ctx.drawImage(img, 0, 0);
    const out = [];
    for (let x = 0; x < img.width; x += 10) {
      const d = ctx.getImageData(x, 0, 1, img.height).data;
      let r = 0, g = 0, bl = 0, n = 0;
      for (let i = 0; i < d.length; i += 4) {
        r += d[i]; g += d[i + 1]; bl += d[i + 2]; n++;
      }
      out.push([x, Math.round(r / n), Math.round(g / n), Math.round(bl / n)]);
    }
    return { width: img.width, out };
  }, `data:image/png;base64,${b64}`);
  await probe.close();

  /* where do the columns jump? report the biggest neighbour deltas */
  const jumps = [];
  for (let i = 1; i < cols.out.length; i++) {
    const a = cols.out[i - 1], b = cols.out[i];
    jumps.push({ x: b[0], d: Math.abs(b[1] - a[1]) + Math.abs(b[2] - a[2]) + Math.abs(b[3] - a[3]) });
  }
  jumps.sort((p, q) => q.d - p.d);
  console.log(`\n${w}x${h} (image ${cols.width}px)`);
  console.log("biggest column jumps:", jumps.slice(0, 8).map((j) => `x=${j.x} d=${j.d}`).join("  "));

  const strip = cols.out.filter(([x]) => x >= 0 && x <= 320).map(([x, r, g, b]) => `x${x}:${r},${g},${b}`);
  console.log("0-320px:", strip.filter((_, i) => i % 3 === 0).join(" "));
  await page.close();
}
await browser.close();
"}}


