}

/* pixel diff outside the headline/copy column */
const load = async (file) => {
  const b64 = fs.readFileSync(file).toString("base64");
  const page = await browser.newPage();
  await page.setContent("<canvas id=c></canvas>");
  const data = await page.evaluate(async (url) => {
    const img = new Image();
    img.src = url;
    await img.decode();
    const c = document.getElementById("c");
    c.width = img.width;
    c.height = img.height;
    const ctx = c.getContext("2d");
    ctx.drawImage(img, 0, 0);
    return { w: img.width, h: img.height, d: Array.from(ctx.getImageData(0, 0, img.width, img.height).data) };
  }, `data:image/png;base64,${b64}`);
  await page.close();
  return data;
};

for (const [w, h] of [[1920, 1080], [1440, 900]]) {
  const a = await load(`docs/hero-shots/headline/before-${w}x${h}.png`);
