  const region = { x0: Math.round(w * 0.4), x1: w, y0: 0, y1: h };
  let diff = 0;
  let total = 0;
  let maxDelta = 0;
  for (let y = region.y0; y < region.y1; y += 2) {
    for (let x = region.x0; x < region.x1; x += 2) {
      const i = (y * a.w + x) * 4;
      const d = Math.abs(a.d[i] - b.d[i]) + Math.abs(a.d[i + 1] - b.d[i + 1]) + Math.abs(a.d[i + 2] - b.d[i + 2]);
      if (d > 6) diff++;
      total++;
      maxDelta = Math.max(maxDelta, d);
    }
