{"kind":"tool","id":"lVLPkepiQBs","toolName":"write_file","input":{"path":".tmp-film.mjs","instructions":"Capture a filmstrip of the headline during first load","content":"import { chromium } from "@playwright/test";

const URL = "http://127.0.0.1:5199/";
const OUT = process.argv[2] || "film";
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });

const t0 = Date.now();
await page.goto(URL, { waitUntil: "commit" });

const marks = [400, 700, 900, 1050, 1200, 1350, 1500, 1700, 2000, 2600, 3200];
const shots = [];
for (const m of marks) {
  const wait = m - (Date.now() - t0);
  if (wait > 0) await page.waitForTimeout(wait);
  const state = await page.evaluate(() => {
    const lines = [...document.querySelectorAll(".h1-line")];
    return {
      t: Math.round(performance.now()),
      font: document.fonts.status,
      loaded: [...document.fonts].map((f) => `${f.family.split(" ")[1]}:${f.status}`),
      lines: lines.map((n) => {
        const s = getComputedStyle(n);
        const r = n.getBoundingClientRect();
        return { op: s.opacity, clip: s.clipPath, y: s.transform, top: Math.round(r.top), w: Math.round(r.width) };
      }),
    };
  });
  const box = await page.evaluate(() => {
    const l = document.querySelector(".hero-h1");
    const r = l.getBoundingClientRect();
    return { x: Math.max(0, Math.round(r.left) - 8), y: Math.max(0, Math.round(r.top) - 12), w: Math.round(r.width) + 16, h: Math.round(r.height) + 24 };
  });
  const file = `/tmp/film-${OUT}-${String(m).padStart(4, "0")}.png`;
  await page.screenshot({ path: file, clip: box });
  shots.push({ m, state, file });
  console.log(m, JSON.stringify(state.lines), "font", state.font, state.loaded.join(" "));
}

console.log(JSON.stringify(shots.map((s) => s.file)));

// stitch the crops into one tall sheet
const { chromium: c2 } = await import("@playwright/test");
const b2 = await c2.launch();
const p2 = await b2.newPage({ viewport: { width: 900, height: 600 } });
const imgs = shots.map((s) => `file:///${s.file.replace(/^\//, "").replace(/^tmp/, "tmp")}`).join(",");
await p2.setContent(`<body style="margin:0;background:#111;font:12px system-ui;color:#eee">
<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:4px">
${shots
  .map(
    (s, i) => `<div><div style="padding:2px 6px">t+${s.m}ms · ${s.state.lines.map((l) => l.op).join("/")}</div>
<img src="${s.file.replace(/^\/tmp\//, "/tmp/")}" style="width:100%;display:block;background:#1a1410"/></div>`
  )
  .join("")}
</div></body>`);
await p2.waitForTimeout(600);
await p2.screenshot({ path: "/tmp/film-sheet.png", fullPage: true });
console.log("sheet /tmp/film-sheet.png");
await b2.close();
await browser.close();
"}}


