{"kind":"tool","id":"lVRLjUhyOrE","toolName":"write_file","input":{"path":".tmp-extent.mjs","instructions":"Measure real glyph extents per headline line against the vault edge","content":"import { chromium } from "@playwright/test";

const URL = "http://127.0.0.1:5199/";
const browser = await chromium.launch();
for (const [w, h] of [[1920, 1080], [1440, 900]]) {
  const page = await browser.newPage({ viewport: { width: w, height: h } });
  await page.goto(URL, { waitUntil: "load" });
  await page.waitForTimeout(3200);
  const m = await page.evaluate(() => {
    const h1 = document.querySelector(".hero-h1");
    const lines = [...document.querySelectorAll(".h1-line")];
    const r = h1.getBoundingClientRect();
    const cs = getComputedStyle(h1);
    const em = getComputedStyle(document.documentElement).getPropertyValue("--h1-em").trim();
    const gap = getComputedStyle(document.documentElement).getPropertyValue("--vault-gap").trim();
    const vleft = getComputedStyle(document.documentElement).getPropertyValue("--vault-left").trim();
    // measure real glyph extents with a Range over each line's text
    const spans = lines.map((n) => {
      const rg = document.createRange();
      rg.selectNodeContents(n);
      const b = rg.getBoundingClientRect();
      return { text: n.textContent.trim(), w: +b.width.toFixed(1), right: +b.right.toFixed(1), top: +b.top.toFixed(1) };
    });
    return {
      fs: cs.fontSize,
      box: { left: +r.left.toFixed(1), right: +r.right.toFixed(1), w: +r.width.toFixed(1), top: +r.top.toFixed(1) },
      spans,
      em,
      gap,
      vleft,
      scrollW: document.documentElement.scrollWidth,
    };
  });
  console.log(w, JSON.stringify(m, null, 1));
  await page.screenshot({ path: `/tmp/hero-${w}.png` });
  await page.close();
}
await browser.close();
"}}


