const URL = "http://127.0.0.1:5199/";
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
await page.addInitScript(() => {
  const rows = (window.__rows = []);
  const tick = () => {
    const lines = [...document.querySelectorAll(".h1-line")];
    const curved = lines[2] ? getComputedStyle(lines[2]).opacity : null;
    rows.push({
      t: Math.round(performance.now()),
      op: lines.map((n) => +(+getComputedStyle(n).opacity).toFixed(3)),
      y: lines.map((n) => {
        const m = new DOMMatrixReadOnly(getComputedStyle(n).transform === "none" ? "" : getComputedStyle(n).transform);
        return +m.f.toFixed(1);
      }),
      curved,
    });
    if (rows.length < 320) requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
});
await page.goto(URL, { waitUntil: "commit" });
await page.waitForTimeout(900);
await page.waitForTimeout(900);
await page.screenshot({ path: "/tmp/enter-mid.png", clip: { x: 60, y: 300, width: 720, height: 280 } });
await page.waitForTimeout(3000);
const rows = await page.evaluate(() => window.__rows);
const started = rows.findIndex((r) => r.op[0] !== 0);
const t0 = rows[started].t;
const done = rows.findIndex((r) => r.op[0] === 1 && r.op[1] === 1 && r.op[2] === 1);
console.log("first moving frame at", t0, JSON.stringify(rows[started]));
console.log("all lines landed at", rows[done].t, `(+${rows[done].t - t0}ms after the first line moved)`);
for (let i = started; i <= Math.min(done + 3, rows.length - 1); i += 2) {
  const r = rows[i];
  console.log(`  +${r.t - t0}ms  op ${r.op.join("/")}  y ${r.y.join("/")}`);
}
await browser.close();
"}}


